#pragma once
#include <filesystem>
#include <memory>
#include <string_view>
#include "IOBuffer.h"
#include "MappedReadOnlyFile.h"
#include "FileDescriptor.h"
namespace ws {
namespace http {
class ConnectionImpl {
public:
    using Ptr = std::shared_ptr<ConnectionImpl>;

    static void SetRootDirectory(std::filesystem::path dir) noexcept {
        root_dir_ = std::move(dir);
    }

    static std::filesystem::path GetRootDirectory() noexcept {
        return root_dir_;
    }

    void Close() noexcept {
        // Implementation for closing the connection
    }

    bool Valid() const noexcept {
        return socket_ != invalid_file_descriptor;
    }

    FileDescriptor Socket() const noexcept {
        return socket_;
    }

    std::size_t Receive() {
        // Implementation for receiving data
        return 0; // Placeholder return value
    }

    std::size_t Send() {
        // Implementation for sending data
        return 0; // Placeholder return value
    }

    bool KeepAlive() const noexcept {
        return keep_alive_;
    }

    bool Process() noexcept {
        if (read_buf_.ReadableSize() == 0) {
            return false;
        }

        Request request(read_buf_);
        request.Parse(read_buf_);

        Response response(root_dir_);
        keep_alive_ = request.KeepAlive();
        response.SetKeepAlive(keep_alive_);

        std::optional<std::string_view> error_msg;
        if (error_msg.has_value()) {
            response.Build(write_buf_, StatusCode::BadRequest, *error_msg);
            return false;
        }

        auto path = request.Path();
        if (path.empty() || path == "/") {
            path = index_page;
        }

        StatusCode status_code;
        auto file = response.Build(write_buf_, std::move(path), status_code);
        if (file.has_value()) {
            file_ = std::move(*file);
        } else {
            status_code = StatusCode::NotFound;
        }

        return true;
    }

private:
    static constexpr std::string_view true_tag {"true"};
    static constexpr std::string_view false_tag {"false"};
    explicit ConnectionImpl(FileDescriptor socket) noexcept : socket_(socket) {}
    virtual ~ConnectionImpl() noexcept = default;

    static std::filesystem::path root_dir_;
    FileDescriptor socket_ {invalid_file_descriptor};
    bool keep_alive_ {false};
    IOBuffer read_buf_;
    IOBuffer write_buf_;
    MappedReadOnlyFile file_;
    static constexpr std::string_view index_page {"index.html"};
};
} // namespace http
} // namespace ws

