#pragma once
#include <memory>
#include <optional>
#include <string_view>
#include "Buffer.h"
#include "Parameters.h"
namespace ws {
namesapce http {
class Request {
public:
    class State;

    Request() noexcept = default;

    explicit Request(Buffer& buf) {
        Parse(buf);
    }

    ~Request() noexcept = default;

    void Parse(Buffer& buf);

    std::optional<std::string_view> Header(std::string_view key) const noexcept {
        auto it = headers_.find(key);
        if (it != headers_.end()) {
            return it->second;
        }
        return std::nullopt;
    }

    std::optional<std::string_view> Post(std::string_view key) const noexcept {
        auto it = post_.find(key);
        if (it != post_.end()) {
            return it->second;
        }
        return std::nullopt;
    }

    std::size_t PostSize() const noexcept {
        return post_.size();
    }

    http::Method Method() const noexcept {
        return method_;
    }

    std::string_view Path() const noexcept {
        return path_;
    }

    std::string_view Version() const noexcept {
        return version_;
    }

    bool KeepAlive() const noexcept {
        auto header = Header("Connection");
        if (header && *header == "keep-alive") {
            return true;
        }
        return false;
    }

private:
    void SetState(std::unique_ptr<State> state) noexcept {
        state_ = std::move(state);
    }

    void Clear() noexcept {
        headers_.clear();
        post_.clear();
        method_ = Method::Get;
        version_.clear();
        path_.clear();
    }

    std::unique_ptr<State> state_;
    http::Method method_ {http::Method::Get};
    std::string version_;
    std::string path_;
    Parameters headers_;
    Parameters post_;
};
} // namespace http
} // namespace ws

#pragma once
#include <memory>
#include <optional>
#include "Buffer.h"
#include "Parameters.h"
#include "StatusCode.h"
namespace ws {
namesapce http {
class Response {
public:
    explicit Response(std::filesystem::path root_dir) noexcept : root_dir_(std::move(root_dir)) {}

    ~Response() noexcept = default;

    Response(const Response&) = delete;
    Response(Response&&) = delete;
    Response& operator=(const Response&) = delete;
    Response& operator=(Response&&) = delete;

    Response& SetKeepAlive(bool set) noexcept {
        keep_alive_ = set;
        return *this;
    }

    std::optional<MappedReadOnlyFile> Build(Buffer& buf, std::filesystem::path file, StatusCode& code) noexcept {
        file_path_ = std::move(file);
        CheckFile();
        if (!file_.IsValid()) {
            code = StatusCode::NotFound;
            AddPredefinedErrorContent(buf, "Not Found");
            return std::nullopt;
        }
        Build(buf);
        code = status_code_;
        return file_;
    }

    void Build(Buffer& buf, std::filesystem::path html, const Parameters& params, StatusCode& code) noexcept {
        file_path_ = std::move(html);
        AddStatusLine(buf);
        AddHeaders(buf);
        AddParamContent(buf, params);
        status_code_ = code;
    }

    void Build(Buffer& buf, StatusCode code, std::string msg = "") noexcept {
        status_code_ = code;
        AddStatusLine(buf);
        AddHeaders(buf);
        AddPredefinedErrorContent(buf, msg);
    }

private:
    void Clear() noexcept {
        file_path_.clear();
        file_.Close();
        keep_alive_ = false;
        status_code_ = StatusCode::OK;
    }

    void Build(Buffer& buf, const Parameters* params = nullptr) noexcept {
        AddStatusLine(buf);
        AddHeaders(buf);
        if (params) {
            AddParamContent(buf, *params);
        } else {
            AddMappedContent(buf);
        }
    }

    void CheckFile() {
        MapFile();
    }

    void MapFile() {
        file_ = MappedReadOnlyFile(file_path_);
    }

    void AddStatusLine(Buffer& buf) const noexcept {
        // Implementation for adding status line to buffer
    }

    void AddHeaders(Buffer& buf) const noexcept {
        // Implementation for adding headers to buffer
    }

    void AddMappedContent(Buffer& buf) noexcept {
        // Implementation for adding mapped file content to buffer
    }

    void AddParamContent(Buffer& buf, const Parameters& params) const noexcept {
        // Implementation for adding parameter content to buffer
    }

    void AddPredefinedErrorContent(Buffer& buf, std::string_view msg = "") noexcept {
        // Implementation for adding predefined error content to buffer
    }

    std::filesystem::path root_dir_;
    std::filesystem::path file_path_;
    MappedReadOnlyFile file_;
    bool keep_alive_ {false};
    StatusCode status_code_ {StatusCode::OK};
};
} // namespace http
} // namespace ws

